function replace(long)
  local tableint={}
  for i=1,long do
    tableint[i]=i
  end
  return shuffle(tableint)
end
function shuffle(t)
  if type(t)~="table" then
    return
  end
  local tab={}
  local index=1
  while #t~=0 do
    local n=math.random(0,#t)
    if t[n]~=nil then
      tab[index]=t[n]
      table.remove(t,n)
      index=index+1
    end
  end
  return tab
end

