function Encryption_dzsh(Text)
  local bytes=gg.bytes(Text)
  local bytesi=replace(#bytes)
  local text={"{","{"}
  for s=1,#bytes do
    text[1]=text[1]..(bytes[bytesi[s]]-bytesi[s])..","
    text[2]=text[2]..bytesi[s]..","
  end
  text[1]=text[1].."}"
  text[2]=text[2].."}"
  return text
end

function timeseed()
