    hexget[i]=hexget[i]+#Defcode-hexget_int
  end
  seedseas=hexget
  return 'local tsx='..(tsx-sumrandoms)..'+FSRBIT\nlocal tsy='..(tsy+sumrandoms1)..'-FSRBIV\nlocal micode='..(micodestr)..'\nwhile tsx<tsy do os.exit()end\nlocal loadFile=gg.getFile()\nlocal loadStr=io.open(loadFile):read("*a")\nlocal Defcode={((loadStr:sub(5,10)..string.sub(loadStr,-tsx,-tsy))):byte(0,-1)}\nlocal hexget,hexget_int,micode_c={},0,0\nmicode={micode:byte(0,-1)} Mmicode=micode\nfor i=1,#Defcode do\nmicode_c=micode_c==#micode and 1 or micode_c+1\nDefcode[i]=micode[micode_c]*2+Defcode[i]\nend\nfor i=1,10 do\nhexget_int=hexget_int==#Defcode and 1 or hexget_int+1\nhexget[i]=(Defcode[hexget_int]*hexget_int+Defcode[#Defcode-hexget_int+1])\nhexget[i]=hexget[i]+#Defcode-hexget_int\nend\nlocal seedseas=hexget\n'
end

function getcodestr()
  gg.supertip("✅:随机混淆生成中……")
  if not seedseas then seastrs=timeseed() end
  local arrstr="MRX.map={};\nlocal Searr,mapsum={},0\n"..M_M().."\n"
  local sum,arrdate=0,{}
  mapsdate={}
  for i=1,1 do
    arrdate[i]={}
    for j=1,1 do
      sum=sum+1
      local Tempnumber=math.random(25,48)
      arrdate[i][j]=Tempnumber
      if j==1 then
        arrstr=arrstr.."MRX.map["..i.."]={"..Tempnumber..","
       elseif j==10 then
        arrstr=arrstr..Tempnumber.."};"
       else
        arrstr=arrstr..Tempnumber..","
      end
    end
    arrstr=arrstr.."\n"
  end
  mixagain=0
  arrstr=arrstr.."\n"..seastrs.."\nlocal lenmaps=#MRX.map+1;\nfor i=1,lenmaps-1 do\nt3=t3 or 0\n t3=(t3==#seedseas and 1 or t3+1)\nSearr[i]=0;\n  for j=1,#MRX.map[i] do\n  local jz=(i+j-1)%11;\n   if jz==0 then jz=1 end\n    if jz%2==0 then\n     Searr[i]=Searr[i]+MRX.map[j][jz];\n     else\n     Searr[i]=Searr[i]-MRX.map[j][jz];\n    end\n  end  \n  Searr[i]=(Searr[i]+seedseas[t3])/2\nend\n"
  local lenmaps=#arrdate+1
  for i=1,lenmaps-1 do
    mixagain=(mixagain==#seedseas and 1 or mixagain+1)
    mapsdate[i]=0
    for j=1,#arrdate[i] do
      local jz=(i+j-1)%1
      if jz==0 then jz=1 end
      if jz%2==0 then
        mapsdate[i]=mapsdate[i]+arrdate[j][jz]
       else
        mapsdate[i]=mapsdate[i]-arrdate[j][jz]
      end
    end
    mapsdate[i]=(mapsdate[i]+seedseas[mixagain])/2
  end
  while arrstr:find(";\n") do
    arrstr=arrstr:gsub(";\n","\n"..randtext(),1)
  end
  gg.supertip("✅:生成完毕")
  return arrstr
end

