function push(bits)
  local out=nil
  if dates==nil then
    instdates=bits
    datesdi=1
    dates={}
  end
  dates[datesdi]=bits
  if datesdi~=1 and bits==instdates then
    out=pop()
    if out==nil then
      out=string.char(instdates)..string.char(instdates)
    end
    dates=nil
  end
  datesdi=datesdi+1
  return out
end

