function Revofilename(a)
  local filename=a:gsub("(.-)/","")
  local filepath=a:gsub('/[^/]+$','').."/"
  local filenameinfo=filename:gsub(".lua","")
  filepath=filepath..filenameinfo..os.date(".DY.lua")
  return filepath
end

