function SparateFunction(content) assert(type(content)=="table") local temp={} local result={} local i=1 local ends=0 for i=1, #lines do if string.find(lines[i],"^%s*function") then table.insert(temp,lines[i]) ends=ends+1 elseif string.find(lines[i],"^%s*if") or string.find(lines[i],"^%s*for") or string.find(lines[i],"^%s*while") then ends=ends+1 if #temp==0 then table.insert(result,lines[i]) else table.insert(temp,lines[i]) end elseif string.find(lines[i],"^%s*end") then ends=ends-1 if #temp==0 then table.insert(result,lines[i]) else table.insert(temp,lines[i]) end if ends==0 and #temp~=0 then table.insert(result,temp) temp={} end else if #temp==0 then table.insert(result,lines[i]) else table.insert(temp,lines[i]) end end end return result end function Split(szFullString, szSeparator) local nFindStartIndex = 1 local nSplitIndex = 1 local nSplitArray = {} while true do local nFindLastIndex = string.find(szFullString, szSeparator, nFindStartIndex) if not nFindLastIndex then nSplitArray[nSplitIndex] = string.sub(szFullString, nFindStartIndex, string.len(szFullString)) break end nSplitArray[nSplitIndex] = string.sub(szFullString, nFindStartIndex, nFindLastIndex - 1) nFindStartIndex = nFindLastIndex + string.len(szSeparator) nSplitIndex = nSplitIndex + 1 end return nSplitArray end function GetAssignment(content) return string.match(content,"^%s*([LA]%d+_%d+)%s*=%s*([^=]-)%s*$") end function isSetGlobals(content) if string.find(content,"^%s*function") then return true end if string.find(content,"^%s*[LA]%d+_%d+%s*=%s*[LA]%d+_%d+%s*$") then return false end return false end function FilteSpec(content) local spec="().+-*?[^$" for ia=1,string.len(spec) do local suba="%%"..string.sub(spec,ia,ia) content=(string.gsub(content,"%"..string.sub(spec,ia,ia),suba)) end return content end function Replace(content,locals) if isSetGlobals(content) then return content end local _i=0 local _v=0 for _i,_v in pairs(locals) do content=(string.gsub(content,_i,FilteSpec(tostring(_v)))) end return content end function process(flines) local spots={} local funnames={} local result="" for i=1, #flines do if type(flines[i])=="string" then if flines[i]~="" then name,value=GetAssignment(flines[i]) if name~=nil then if string.find(value,"^%s*%{}") then spots[name]=nil result=result..flines[i].."\n" else spots[name]=Replace(value,spots) end elseif string.find(flines[i],"^%s*local") then result=result..flines[i].."\n" local localss=string.match(flines[i],"^%s*local%s*(.-)%s*$") local tlocals=Split(localss,",") for j=1,#tlocals do spots[string.match(tlocals[j],"^%s*([^%s]-)%s*$")]="" end else result=result..(Replace(flines[i],spots)).."\n" end end elseif type(flines[i]=="table") then if i~=#flines then if flines[i][1]~=nil and type(flines[i][1]=="string") then local funspot=string.match(flines[i][1],"function%s*(L%d+_%d+)") local funname= string.match(flines[i+1],"^%s*([^=]-)%s*=%s*"..funspot.."%s*$") if funname~=nil then flines[i][1]=(string.gsub(flines[i][1],funspot,FilteSpec(funname))) flines[i+1]="" end result=result..process(flines[i]).."\n" end end end end return result end function raw(s) for w in string.gmatch(s, '\\(%d%d%d)') do s=string.gsub(s,'\\'..w,string.char(w),1) end return s end function decompileO(ina,out) file=io.open(ina,"rb") script=file:read("*a") file:close() lines=Split(script,"\n") flines=SparateFunction(lines) unraw=process(flines) file=io.open(out,"wb") file:write(unraw) file:close() final=raw(unraw) file=io.open(out,"wb") file:write(final) file:close() end function decompileOO(ina) decompileO(ina,ina) end
